def previous_business_day(day_num, weekend_days):
    d = day_num - 1
    while d % 7 in weekend_days:
        d -= 1
    return d

def mask_formatted_phone(phone):
    parts = phone.split("-")
    parts[1] = "*" * len(parts[1])
    return "-".join(parts)

def flatten_and_dedupe(nested):
    seen = set()
    out = []
    for sub in nested:
        for x in sub:
            if x not in seen:
                seen.add(x)
                out.append(x)
    return out

def split_keep_delimiters(s, delims):
    delim_set = set(delims)
    tokens = []
    current = []
    for c in s:
        if c in delim_set:
            if current:
                tokens.append("".join(current))
                current = []
            tokens.append(c)
        else:
            current.append(c)
    if current:
        tokens.append("".join(current))
    return tokens

def count_items_by_category(items, categories):
    res = {}
    for it in items:
        cat = categories.get(it, "other")
        res[cat] = res.get(cat, 0) + 1
    return res

def is_valid_isbn10(s):
    s = s.replace('-', '')
    if len(s) != 10:
        return False
    if not s[:9].isdigit():
        return False
    if not (s[9].isdigit() or s[9] == 'X'):
        return False
    total = 0
    for i, ch in enumerate(s):
        val = 10 if ch == 'X' else int(ch)
        total += val * (10 - i)
    return total % 11 == 0

def is_valid_luhn_number(s):
    if len(s) < 2 or not s.isdigit():
        return False
    total = 0
    for i, ch in enumerate(reversed(s)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

def is_balanced_ignoring_letters(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    stack = []
    for c in s:
        if c in opens:
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
    return not stack

def count_by_sign(nums):
    d = {"positive": 0, "negative": 0, "zero": 0}
    for x in nums:
        if x > 0:
            d["positive"] += 1
        elif x < 0:
            d["negative"] += 1
        else:
            d["zero"] += 1
    return d

def is_self_number(n):
    lo = max(0, n - 100)
    for m in range(lo, n):
        if m + sum(int(d) for d in str(m)) == n:
            return False
    return True

def csv_quote(s):
    if "," in s or '"' in s or "\n" in s:
        return '"' + s.replace('"', '""') + '"'
    return s

def medians_of_prefixes(nums):
    result = []
    cur = []
    for x in nums:
        cur.append(x)
        s = sorted(cur)
        n = len(s)
        mid = n // 2
        if n % 2 == 1:
            result.append(float(s[mid]))
        else:
            result.append((s[mid - 1] + s[mid]) / 2)
    return result

def partition_even_odd_values(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def collatz_max_value(n):
    m = n
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        m = max(m, n)
    return m

def count_occurrences(lst):
    d = {}
    for x in lst:
        d[x] = d.get(x, 0) + 1
    return d

def rank_with_average_ties(nums):
    s = sorted(nums)
    n = len(s)
    avg_rank = {}
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        avg = (i + 1 + j) / 2
        for k in range(i, j):
            avg_rank[s[k]] = avg
        i = j
    return [avg_rank[x] for x in nums]

def classify_char_string(s):
    vowels = set("aeiouAEIOU")
    result = []
    for c in s:
        if c.isalpha():
            result.append('V' if c in vowels else 'C')
        elif c.isdigit():
            result.append('D')
        else:
            result.append('O')
    return "".join(result)

def reorder_date_dmy_to_ymd(s):
    d, m, y = s.split("-")
    return f"{y}-{m}-{d}"

def most_frequent_value(lst):
    if not lst:
        return None
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    best = None
    best_count = -1
    for x in lst:
        if counts[x] > best_count:
            best_count = counts[x]
            best = x
    return best

def wrap_single_quotes(s):
    escaped = s.replace("'", "\\'")
