def column_layout(items, ncols, width):
    rows = []
    for i in range(0, len(items), ncols):
        chunk = items[i:i + ncols]
        rows.append(' '.join(c.ljust(width) for c in chunk))
    return rows

def longest_non_decreasing_run_length(lst):
    if not lst:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] >= lst[i - 1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def balance_index_last(lst):
    total = sum(lst)
    left = 0
    result = -1
    for i, x in enumerate(lst):
        right = total - left - x
        if left == right:
            result = i
        left += x
    return result

def find_min_sum_subarray_of_size_k(lst, k):
    best = cur = sum(lst[:k])
    for i in range(k, len(lst)):
        cur += lst[i] - lst[i - k]
        best = min(best, cur)
    return best

def format_percent_from_ratio(numerator, denominator):
    if denominator == 0:
        return "N/A"
    return f"{numerator / denominator * 100:.2f}%"
